class Database:
    def __init__(self):
        self.tables = {}

    def createTable(self, tableName, columns):
        if tableName not in self.tables:
            self.tables[tableName] = {'columns': columns, 'data': []}

    def insertData(self, tableName, data):
        if tableName in self.tables:
            self.tables[tableName]['data'].append(data)

    def queryData(self, tableName, conditions):
        if tableName in self.tables:
            table_data = self.tables[tableName]['data']
            result = []
            for row in table_data:
                if all(row.get(col) == value for col, value in conditions.items()):
                    result.append(row)
            return result
        return []
