You should use TypeScript for this implementation and ensure that the component is generic, allowing it to handle different types of fetched data.

```typescript
import React from 'react'

interface IApiError {
  // Define the structure of the API error object
}

interface IFetchHandlerProps<T> {
  data?: T
  isLoading: boolean
  children: JSX.Element | JSX.Element[] | ((data: T) => JSX.Element)
  error: IApiError | null
  loadingComponent?: JSX.Element | JSX.Element[]
}

const FetchHandler = <T extends any>({
  isLoading,
  data,
  children,
  error,
  loadingComponent,
}: IFetchHandlerProps<T>): JSX.Element => {
